// Package tictactoe implements a two-player tic-tac-toe game realm.
//
// Call NewGame to start a game as X, Join to sign up as O, and Play to
// place a mark. Render shows the board and whose turn it is.
package tictactoe

type cell int

const (
	empty cell = iota
	markX
	markO
)

func (c cell) String() string {
	switch c {
	case markX:
		return "X"
	case markO:
		return "O"
	default:
		return "·"
	}
}

var (
	board   [9]cell
	playerX address
	playerO address
	turn    cell
	winner  cell
	started bool
	over    bool
)

var winLines = [8][3]int{
	{0, 1, 2}, {3, 4, 5}, {6, 7, 8},
	{0, 3, 6}, {1, 4, 7}, {2, 5, 8},
	{0, 4, 8}, {2, 4, 6},
}

// NewGame starts a fresh game. The caller becomes X. Panics if a game is
// already in progress.
func NewGame(cur realm) {
	if started && !over {
		panic("a game is already in progress")
	}
	board = [9]cell{}
	playerX = cur.Previous().Address()
	playerO = address("")
	turn = markX
	winner = empty
	started = true
	over = false
}

// Join signs the caller up as O for the in-progress game. Panics if there
// is no open game, or the O seat is already taken.
func Join(cur realm) {
	if !started || over {
		panic("no open game to join")
	}
	caller := cur.Previous().Address()
	if caller == playerX {
		panic("already playing as X in this game")
	}
	if playerO != address("") {
		panic("game already has two players")
	}
	playerO = caller
}

// Play places the caller's mark at pos (0-8, row-major). Panics on an
// invalid move: out-of-range position, occupied cell, wrong turn, or a
// caller that isn't one of the two players.
func Play(cur realm, pos int) {
	if !started || over {
		panic("no active game")
	}
	if pos < 0 || pos > 8 {
		panic("position must be between 0 and 8")
	}
	if board[pos] != empty {
		panic("cell already occupied")
	}
	if playerO == address("") {
		panic("waiting for a second player to join")
	}

	caller := cur.Previous().Address()
	var mark cell
	switch caller {
	case playerX:
		mark = markX
	case playerO:
		mark = markO
	default:
		panic("caller is not a player in this game")
	}
	if mark != turn {
		panic("not your turn")
	}

	board[pos] = mark

	if hasWon(mark) {
		winner = mark
		over = true
		return
	}
	if isFull() {
		over = true
		return
	}
	if turn == markX {
		turn = markO
	} else {
		turn = markX
	}
}

func hasWon(mark cell) bool {
	for _, line := range winLines {
		if board[line[0]] == mark && board[line[1]] == mark && board[line[2]] == mark {
			return true
		}
	}
	return false
}

func isFull() bool {
	for _, c := range board {
		if c == empty {
			return false
		}
	}
	return true
}

// Render renders the current board as markdown.
func Render(path string) string {
	out := "# Tic-Tac-Toe\n\n"
	if !started {
		out += "No game yet. Call `NewGame` to start one.\n"
		return out
	}

	out += "```\n"
	for row := 0; row < 3; row++ {
		for col := 0; col < 3; col++ {
			idx := row*3 + col
			out += board[idx].String()
			if col < 2 {
				out += " | "
			}
		}
		out += "\n"
		if row < 2 {
			out += "--+---+--\n"
		}
	}
	out += "```\n\n"

	out += "X: " + playerX.String() + "\n\n"
	if playerO != address("") {
		out += "O: " + playerO.String() + "\n\n"
	} else {
		out += "O: (waiting for a player to `Join`)\n\n"
	}

	switch {
	case over && winner != empty:
		out += "**" + winner.String() + " wins!**\n"
	case over:
		out += "**Draw.**\n"
	default:
		out += "Turn: **" + turn.String() + "** (position 0-8, row-major:\n\n```\n0 | 1 | 2\n--+---+--\n3 | 4 | 5\n--+---+--\n6 | 7 | 8\n```)\n"
	}

	return out
}

// Package tictactoe is a two-player tic-tac-toe realm.
package tictactoe

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Game holds the full state of one tic-tac-toe match.
// Board is indexed 0-8, row-major (0,1,2 / 3,4,5 / 6,7,8).
type Game struct {
	ID       int64
	X        address // ❌ creator, moves first
	O        address // ⭕ opponent
	Board    [9]int  // 0 empty, 1 = X, 2 = O
	Turn     int     // whose turn: markX or markO
	Winner   int     // empty until decided; markX/markO = winner
	Draw     bool
	Finished bool
}

const (
	empty = 0
	markX = 1
	markO = 2
)

var (
	games  avl.Tree // id string -> *Game
	nextID int64
)

// wins[i] lists the eight winning lines as cell-index triples.
var winLines = [8][3]int{
	{0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // rows
	{0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // cols
	{0, 4, 8}, {2, 4, 6}, // diagonals
}

func idKey(id int64) string {
	return strconv.FormatInt(id, 10)
}

func getGame(id int64) *Game {
	v, ok := games.Get(idKey(id))
	if !ok {
		panic("game not found")
	}
	return v.(*Game)
}

// NewGame creates a match between the caller (❌) and opponent (⭕).
// The caller moves first. Returns the new game id.
func NewGame(cur realm, opponent address) int64 {
	caller := cur.Previous().Address()
	if opponent == caller {
		panic("opponent must differ from caller")
	}
	if opponent == "" {
		panic("opponent address required")
	}

	id := nextID
	nextID++

	games.Set(idKey(id), &Game{
		ID:   id,
		X:    caller,
		O:    opponent,
		Turn: markX,
	})

	return id
}

// Play places the caller's mark at the given cell (0-8) of gameID.
// Enforces turn order, rejects out-of-range or occupied cells, and
// detects a win or a draw.
func Play(cur realm, gameID int64, cell int) {
	caller := cur.Previous().Address()
	g := getGame(gameID)

	if g.Finished {
		panic("game already finished")
	}
	if cell < 0 || cell > 8 {
		panic("cell out of range")
	}
	if g.Board[cell] != empty {
		panic("cell already occupied")
	}

	var mark int
	switch caller {
	case g.X:
		mark = markX
	case g.O:
		mark = markO
	default:
		panic("caller is not a player in this game")
	}
	if mark != g.Turn {
		panic("not your turn")
	}

	g.Board[cell] = mark

	if wins(&g.Board, mark) {
		g.Winner = mark
		g.Finished = true
		return
	}
	if full(&g.Board) {
		g.Draw = true
		g.Finished = true
		return
	}

	if g.Turn == markX {
		g.Turn = markO
	} else {
		g.Turn = markX
	}
}

func wins(b *[9]int, mark int) bool {
	for _, line := range winLines {
		if b[line[0]] == mark && b[line[1]] == mark && b[line[2]] == mark {
			return true
		}
	}
	return false
}

func full(b *[9]int) bool {
	for _, v := range b {
		if v == empty {
			return false
		}
	}
	return true
}

func glyph(v int) string {
	switch v {
	case markX:
		return "❌"
	case markO:
		return "⭕"
	default:
		return "·"
	}
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// Render draws the board with ❌⭕· and shows whose turn / the winner.
// path "" lists all games; path "<id>" shows a single board.
func Render(path string) string {
	if path == "" {
		return renderList()
	}
	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil {
		return "> [!WARNING]\n> Path not found"
	}
	v, ok := games.Get(idKey(id))
	if !ok {
		return "> [!WARNING]\n> Path not found"
	}
	return renderGame(v.(*Game))
}

func renderList() string {
	if games.Size() == 0 {
		return "# Tic-Tac-Toe\n\nNo games yet."
	}
	var out strings.Builder
	out.WriteString("# Tic-Tac-Toe\n\n")
	games.Iterate("", "", func(key string, value any) bool {
		g := value.(*Game)
		status := "in progress"
		switch {
		case g.Winner == markX:
			status = "❌ wins"
		case g.Winner == markO:
			status = "⭕ wins"
		case g.Draw:
			status = "draw"
		}
		out.WriteString("- [Game " + key + "](" + key + "): " +
			short(g.X) + " (❌) vs " + short(g.O) + " (⭕) — " + status + "\n")
		return false
	})
	return out.String()
}

func renderGame(g *Game) string {
	var out strings.Builder
	out.WriteString("# Game " + strconv.FormatInt(g.ID, 10) + "\n\n")
	out.WriteString("❌ " + short(g.X) + " vs ⭕ " + short(g.O) + "\n\n")

	for row := 0; row < 3; row++ {
		cells := make([]string, 3)
		for col := 0; col < 3; col++ {
			cells[col] = glyph(g.Board[row*3+col])
		}
		out.WriteString(strings.Join(cells, " | ") + "\n")
		if row < 2 {
			out.WriteString("---------\n")
		}
	}

	out.WriteString("\n")
	switch {
	case g.Winner == markX:
		out.WriteString("❌ wins!\n")
	case g.Winner == markO:
		out.WriteString("⭕ wins!\n")
	case g.Draw:
		out.WriteString("Draw.\n")
	case g.Turn == markX:
		out.WriteString("Turn: ❌\n")
	default:
		out.WriteString("Turn: ⭕\n")
	}
	return out.String()
}

package canvas

import (
	"strings"
)

const (
	width  = 9
	height = 13
)

var (
	rows       [height]string
	lastCaller address
	hasDrawn   bool
)

func init() {
	blank := strings.Repeat(".", width)
	for i := 0; i < height; i++ {
		rows[i] = blank
	}
}

func pixel(c byte) string {
	switch c {
	case '.':
		return "⬛"
	case 'R':
		return "\U0001f7e5"
	case 'S':
		return "\U0001f7e7"
	case 'Y':
		return "\U0001f7e8"
	case 'G':
		return "\U0001f7e9"
	case 'B':
		return "\U0001f7e6"
	case 'W':
		return "⬜"
	case 'H':
		return "\U0001f7eb"
	case 'P':
		return "\U0001f7ea"
	default:
		return "⬛"
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	return digits
}

// Draw repaints the canvas from ASCII rows separated by newlines.
// Each row must be exactly 9 characters using the palette:
// . R S Y G B W H P
func Draw(cur realm, art string) string {
	lines := strings.Split(strings.TrimSpace(art), "\n")
	if len(lines) != height {
		panic("canvas: expected " + itoa(height) + " rows, got " + itoa(len(lines)))
	}
	var clean [height]string
	for i, line := range lines {
		l := strings.TrimSpace(line)
		if len(l) != width {
			panic("canvas: row " + itoa(i) + " must be " + itoa(width) + " chars")
		}
		clean[i] = l
	}
	rows = clean
	hasDrawn = true
	lastCaller = cur.Previous().Address()
	return "canvas updated"
}

func Render(path string) string {
	var b strings.Builder
	b.WriteString("```\n")
	for i := 0; i < height; i++ {
		row := rows[i]
		for j := 0; j < width; j++ {
			b.WriteString(pixel(row[j]))
		}
		b.WriteString("\n")
	}
	b.WriteString("```\n\n")
	if !hasDrawn {
		b.WriteString("*no updates yet*\n")
	} else {
		b.WriteString("last updated by: " + lastCaller.String() + "\n")
	}
	return b.String()
}

package canvas

import "strings"

const (
	width  = 9
	height = 13
)

var (
	grid        [height]string
	lastUpdater address
)

func init() {
	blank := strings.Repeat(".", width)
	for i := 0; i < height; i++ {
		grid[i] = blank
	}
}

// Draw repaints the canvas from height rows of width ASCII letters each.
func Draw(cur realm, art string) {
	lines := strings.Split(strings.TrimSpace(art), "\n")
	if len(lines) != height {
		panic("art must have exactly 13 rows")
	}
	for i, line := range lines {
		if len(line) != width {
			panic("each row must have exactly 9 characters")
		}
		grid[i] = line
	}
	lastUpdater = cur.Previous().Address()
}

func emoji(c byte) string {
	switch c {
	case 'R':
		return "\U0001F7E5"
	case 'S':
		return "\U0001F7E7"
	case 'Y':
		return "\U0001F7E8"
	case 'G':
		return "\U0001F7E9"
	case 'B':
		return "\U0001F7E6"
	case 'W':
		return "⬜"
	case 'H':
		return "\U0001F7EB"
	case 'P':
		return "\U0001F7EA"
	default:
		return "⬛"
	}
}

func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("```\n")
	for _, row := range grid {
		for i := 0; i < len(row); i++ {
			sb.WriteString(emoji(row[i]))
		}
		sb.WriteString("\n")
	}
	sb.WriteString("```\n\n")
	if lastUpdater == "" {
		sb.WriteString("Last updated by: (no updates yet)\n")
	} else {
		sb.WriteString("Last updated by: " + lastUpdater.String() + "\n")
	}
	return sb.String()
}

// Package canvas is a 9x13 pixel-art board rendered as LED-emoji pixels.
//
// Draw repaints the whole grid from a simple ASCII sketch and records
// who painted it. The canvas starts blank (all pixels off).
package canvas

import "strings"

const (
	numRows = 9
	numCols = 13
)

var (
	grid        [numRows]string
	lastUpdater address
	hasUpdater  bool
)

func init() {
	blank := strings.Repeat(".", numCols)
	for i := range grid {
		grid[i] = blank
	}
}

// Draw repaints the canvas from art: exactly 9 rows separated by
// newlines, each row exactly 13 characters wide. Records the caller
// as the canvas's last updater.
//
// Character legend (unrecognized characters render as off):
//
//	.  off      W  white    R  red     O  orange
//	Y  yellow   G  green    B  blue    P  purple
//	N  brown    K  black
func Draw(cur realm, art string) {
	lines := strings.Split(strings.TrimRight(art, "\n"), "\n")
	if len(lines) != numRows {
		panic("art must have exactly 9 rows")
	}
	for _, line := range lines {
		if len(line) != numCols {
			panic("each row must be exactly 13 characters wide")
		}
	}
	for i, line := range lines {
		grid[i] = line
	}
	lastUpdater = cur.Previous().Address()
	hasUpdater = true
}

func pixel(c byte) string {
	switch c {
	case 'W':
		return "⬜"
	case 'R':
		return "🟥"
	case 'O':
		return "🟧"
	case 'Y':
		return "🟨"
	case 'G':
		return "🟩"
	case 'B':
		return "🟦"
	case 'P':
		return "🟪"
	case 'N':
		return "🟫"
	default:
		return "⬛"
	}
}

// Render draws the current canvas as a fenced grid of LED-emoji pixels
// and reports who last updated it.
func Render(_ string) string {
	var out strings.Builder
	out.WriteString("# canvas\n\n```\n")
	for _, row := range grid {
		for i := 0; i < len(row); i++ {
			out.WriteString(pixel(row[i]))
		}
		out.WriteString("\n")
	}
	out.WriteString("```\n\n")
	if hasUpdater {
		out.WriteString("last updated by: `" + lastUpdater.String() + "`\n")
	} else {
		out.WriteString("last updated by: _(nobody yet, canvas is blank)_\n")
	}
	return out.String()
}

// Package canvas is a 9x13 pixel-art LED canvas. Draw repaints it from
// simple ASCII rows and Render shows the grid plus who last painted it.
package canvas

import (
	"strings"
)

const (
	rows = 9
	cols = 13
)

// led maps an ASCII pixel code to its emoji.
var led = map[byte]string{
	'.': "⬛", // off
	'R': "🟥",
	'O': "🟧",
	'Y': "🟨",
	'G': "🟩",
	'B': "🟦",
	'P': "🟪",
	'W': "⬜",
	'N': "🟫",
}

var (
	grid        [rows]string // each entry is `cols` ASCII pixel codes
	lastPainter address
	painted     bool
)

func init() {
	blank := strings.Repeat(".", cols)
	for i := 0; i < rows; i++ {
		grid[i] = blank
	}
}

// Draw repaints the canvas from ASCII art: `rows` newline-separated rows,
// each exactly 13 characters from the set ".ROYGBPWN". Records the caller
// as the canvas's last painter.
func Draw(cur realm, art string) {
	newGrid := parseArt(art)
	grid = newGrid
	lastPainter = cur.Previous().Address()
	painted = true
}

// parseArt validates ASCII art into a grid, panicking on any malformed input.
func parseArt(art string) [rows]string {
	lines := strings.Split(art, "\n")
	if len(lines) != rows {
		panic("canvas: need exactly 9 rows")
	}
	for _, line := range lines {
		if len(line) != cols {
			panic("canvas: each row must be exactly 13 characters")
		}
		for i := 0; i < len(line); i++ {
			if _, ok := led[line[i]]; !ok {
				panic("canvas: unknown pixel code '" + string(line[i]) + "'")
			}
		}
	}

	var newGrid [rows]string
	copy(newGrid[:], lines)
	return newGrid
}

// Render draws the canvas as LED-emoji pixels and names the last painter.
func Render(_ string) string {
	var out strings.Builder
	out.WriteString("# Canvas\n\n```\n")
	for i := 0; i < rows; i++ {
		row := grid[i]
		for j := 0; j < len(row); j++ {
			out.WriteString(led[row[j]])
		}
		out.WriteString("\n")
	}
	out.WriteString("```\n\n")
	if painted {
		out.WriteString("Last updated by: " + lastPainter.String() + "\n")
	} else {
		out.WriteString("Blank canvas — no one has painted yet.\n")
	}
	return out.String()
}

// Package canvas is a shared 9x13 pixel-art canvas rendered as LED emoji.
//
// Draw repaints the whole grid from simple ASCII rows and records the
// caller's address as the last updater; Render shows the grid plus that
// address.
package canvas

import "strings"

const (
	gridWidth  = 9
	gridHeight = 13
)

var (
	grid       [gridHeight]string
	lastEditor address
)

func init() {
	blank := strings.Repeat(".", gridWidth)
	for r := 0; r < gridHeight; r++ {
		grid[r] = blank
	}
}

// emoji maps a palette letter to its LED emoji. Panics on an unknown letter.
func emoji(c byte) string {
	switch c {
	case '.':
		return "⬛"
	case 'R':
		return "🟥"
	case 'S':
		return "🟧"
	case 'Y':
		return "🟨"
	case 'G':
		return "🟩"
	case 'B':
		return "🟦"
	case 'W':
		return "⬜"
	case 'H':
		return "🟫"
	case 'P':
		return "🟪"
	default:
		panic("canvas: invalid pixel character '" + string(c) + "'")
	}
}

// Draw repaints the canvas from art: newline-separated ASCII rows, exactly
// 13 rows of exactly 9 characters each, using the palette
// . R S Y G B W H P (off, red, orange, yellow, green, blue, white, brown, purple).
// Records the caller as the last updater.
func Draw(cur realm, art string) {
	rows := strings.Split(art, "\n")
	if len(rows) != gridHeight {
		panic("canvas: art must have exactly 13 rows")
	}
	for _, row := range rows {
		if len(row) != gridWidth {
			panic("canvas: each row must be exactly 9 characters")
		}
		for i := 0; i < gridWidth; i++ {
			emoji(row[i]) // validates every character before committing
		}
	}
	for i, row := range rows {
		grid[i] = row
	}
	lastEditor = cur.Previous().Address()
}

// Render shows the canvas as LED emoji in a fenced code block, plus the
// address that last called Draw.
func Render(path string) string {
	var out strings.Builder
	out.WriteString("```\n")
	for r := 0; r < gridHeight; r++ {
		row := grid[r]
		for c := 0; c < gridWidth; c++ {
			out.WriteString(emoji(row[c]))
		}
		out.WriteString("\n")
	}
	out.WriteString("```\n\n")

	var zero address
	if lastEditor == zero {
		out.WriteString("*No updates yet.*\n")
	} else {
		out.WriteString("Last updated by: " + lastEditor.String() + "\n")
	}
	return out.String()
}

// Package poll is a single yes/no poll. Each address may vote once;
// voting again updates that address's previous choice and adjusts the tally.
package poll

import (
	"chain"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const question = "Should we ship it?"

const barWidth = 20

var (
	votes     avl.Tree // address.String() -> bool (their current choice)
	yesCount  int
	noCount   int
	lastVoter address
)

// Vote records the caller's yes/no choice. Re-voting updates the caller's
// previous choice and adjusts the tally accordingly. EOA-only.
func Vote(cur realm, choice bool) {
	if !cur.Previous().IsUserCall() {
		panic("only a direct wallet call (MsgCall) may vote")
	}
	addr := cur.Previous().Address()
	key := addr.String()

	if prev, ok := votes.Get(key); ok {
		if prev.(bool) {
			yesCount--
		} else {
			noCount--
		}
	}

	votes.Set(key, choice)
	if choice {
		yesCount++
	} else {
		noCount++
	}
	lastVoter = addr

	chain.Emit("Voted", "address", key, "choice", ufmt.Sprintf("%t", choice))
}

func bar() string {
	total := yesCount + noCount
	if total == 0 {
		out := ""
		for i := 0; i < barWidth; i++ {
			out += "⬛"
		}
		return out
	}

	yesBlocks := yesCount * barWidth / total
	noBlocks := barWidth - yesBlocks

	out := ""
	for i := 0; i < yesBlocks; i++ {
		out += "🟩"
	}
	for i := 0; i < noBlocks; i++ {
		out += "🟥"
	}
	return out
}

func Render(_ string) string {
	out := "# " + question + "\n\n"
	out += bar() + "\n\n"
	out += ufmt.Sprintf("Yes: %d  |  No: %d\n\n", yesCount, noCount)

	if yesCount+noCount == 0 {
		out += "No votes yet.\n"
	} else {
		out += ufmt.Sprintf("Last voter: %s\n", lastVoter.String())
	}
	return out
}

package myboardoptimized

import "strconv"

var (
    boardName string = "Mon Forum Optimisé"
    posts     []string
)

func init() {
    posts = make([]string, 0, 100)
}

func GetBoardName() string {
    return boardName
}

// OPTIMISÉ : Slice au lieu de map + pré-allocation
func CreatePost(content string) int {
    posts = append(posts, content)
    return len(posts)
}

func GetPost(id int) string {
    if id > 0 && id <= len(posts) {
        return posts[id-1]
    }
    return ""
}

func GetPostCount() int {
    return len(posts)
}

// OPTIMISÉ : Limite à 5 posts dans Render
func Render(path string) string {
    output := "# " + boardName + "\n\n"
    output += "## Publications (" + strconv.Itoa(len(posts)) + ")\n\n"

    limit := 5
    if len(posts) < 5 {
        limit = len(posts)
    }

    for i := 0; i < limit; i++ {
        output += strconv.Itoa(i+1) + ". " + posts[i] + "\n\n"
    }

    if len(posts) > 5 {
        output += "... et " + strconv.Itoa(len(posts)-5) + " posts de plus\n\n"
    }

    return output
}
